using System.Net.Http.Json;using System.Security.Claims;using Microsoft.EntityFrameworkCore;using OrderService.Data;using OrderService.Entities;namespace OrderService.Services;public record Line(Guid ProductId,int Quantity);public class BusinessException(string m):Exception(m);public class NotFoundException(string m):Exception(m);public interface IOrder{Task<Order>Create(Guid u,List<Line>lines,CancellationToken c);Task<List<Order>>Mine(Guid u,int p,int s,CancellationToken c);Task<Order?>Get(Guid id,Guid u,bool admin,CancellationToken c);Task<Order?>Cancel(Guid id,Guid u,bool admin,CancellationToken c);}public class InventoryClient(HttpClient h){public async Task<bool>Exists(Guid id,CancellationToken c){var r=await h.GetAsync($"api/products/{id}",c);return r.IsSuccessStatusCode;}public async Task Reduce(Guid id,int q,CancellationToken c){var r=await h.PostAsJsonAsync($"api/products/{id}/reduce_stock",new{quantity=q},c);if(!r.IsSuccessStatusCode)throw new BusinessException("Stock validation failed.");}public async Task Restore(Guid id,int q,CancellationToken c){var r=await h.PostAsJsonAsync($"api/products/{id}/restore_stock",new{quantity=q},c);if(!r.IsSuccessStatusCode)throw new BusinessException("Stock restoration failed.");}}public class OrderService(OrderDbContext db,InventoryClient inv):IOrder{public async Task<Order>Create(Guid u,List<Line>lines,CancellationToken c){if(lines.Count==0)throw new BusinessException("Order requires at least one item.");var done=new List<Line>();try{foreach(var x in lines){if(x.Quantity<=0||!await inv.Exists(x.ProductId,c))throw new BusinessException("Invalid product or quantity.");await inv.Reduce(x.ProductId,x.Quantity,c);done.Add(x);}}catch{foreach(var x in done)try{await inv.Restore(x.ProductId,x.Quantity,CancellationToken.None);}catch{}throw;}var o=new Order{UserId=u,OrderStatus="CONFIRMED",CreatedAt=DateTime.UtcNow,Items=lines.Select(x=>new OrderItem{ProductId=x.ProductId,Quantity=x.Quantity}).ToList()};db.Orders.Add(o);await db.SaveChangesAsync(c);return o;}public Task<List<Order>>Mine(Guid u,int p,int s,CancellationToken c)=>db.Orders.AsNoTracking().Include(x=>x.Items).Where(x=>x.UserId==u).OrderByDescending(x=>x.CreatedAt).Skip((p-1)*s).Take(s).ToListAsync(c);public Task<Order?>Get(Guid id,Guid u,bool a,CancellationToken c)=>db.Orders.AsNoTracking().Include(x=>x.Items).FirstOrDefaultAsync(x=>x.OrderId==id&&(a||x.UserId==u),c);public async Task<Order?>Cancel(Guid id,Guid u,bool a,CancellationToken c){var o=await db.Orders.Include(x=>x.Items).FirstOrDefaultAsync(x=>x.OrderId==id&&(a||x.UserId==u),c);if(o==null)return null;if(o.OrderStatus=="CANCELLED")throw new BusinessException("Already cancelled.");foreach(var x in o.Items)await inv.Restore(x.ProductId,x.Quantity,c);o.OrderStatus="CANCELLED";await db.SaveChangesAsync(c);return o;}}